}

static void *lex_config(struct lexer *lexer)
{
    while (true) {
        int chr = next(lexer);

        if (chr == '\0')
            break;

        if (chr == '\n') {
            emit(lexer, LEXEME_LINEFEED);
            return lex_config;
        }

        if (isspace(chr)) {
            ignore(lexer);
            continue;
        }

        if (chr == '{') {
            emit(lexer, LEXEME_OPEN_BRACKET);
            return lex_config;
        }

        if (chr == '}') {
            emit(lexer, LEXEME_CLOSE_BRACKET);
            return lex_config;
        }

        if (chr == '=') {
            emit(lexer, LEXEME_EQUAL);
            return lex_config;
        }

        if (chr == '#')
            return lex_comment;

        if (chr == '\'' && !strncmp(lexer->pos, "''", 2))
            return lex_multiline_string;
        if (chr == '"' && !strncmp(lexer->pos, "\"\"", 2))
            return lex_multiline_string;

        if (chr == '$' && peek(lexer) == '{')
            return lex_variable;

        if (isstring(chr))
            return lex_string;

        return lex_error(lexer, "Invalid character");
    }

    emit(lexer, LEXEME_LINEFEED);
    emit(lexer, LEXEME_EOF);

    return NULL;
}

